{"path":"/c/Users/Arti/wakefit-clone/src/services/discountService.ts","content":"import { getRepositories } from '@/repositories/supabase'
import type { Discount, DiscountStatus, DiscountType } from '@/features/discounts/types'

export interface DiscountFilters {
  search?: string
  status?: DiscountStatus | 'all'
  type?: DiscountType | 'all'
}

export interface DiscountDraft {
  name: string
  code: string
  description?: string
  type: DiscountType
  value: number
  minOrderValue?: number
  categoryIds?: string[]
  productIds?: string[]
  customerGroup?: Discount['condition']['customerGroup']
  startDate: string
  endDate: string | null
  usageLimit: number | null
  perCustomerLimit: number | null
  stackable: boolean
  oncePerCustomer: boolean
}

function computeStatus(startDate: string, endDate: string | null): DiscountStatus {
  const today = new Date().toISOString().slice(0, 10)
  if (startDate > today) return 'scheduled'
  if (endDate && endDate < today) return 'expired'
  return 'active'
}

export const discountService = {
  async getAll(): Promise<Discount[]> {
    return getRepositories().discounts.getAll()
  },

  async getById(id: string): Promise<Discount | null> {
    return getRepositories().discounts.getById(id)
  },

  async search(filters: DiscountFilters): Promise<Discount[]> {
    let discounts = await getRepositories().discounts.getAll()
    if (filters.search) {
      const q = filters.search.toLowerCase()
      discounts = discounts.filter(
        (d) => d.name.toLowerCase().includes(q) || d.code.toLowerCase().includes(q)
      )
    }
    if (filters.status && filters.status !== 'all') {
      discounts = discounts.filter((d) => d.status === filters.status)
    }
    if (filters.type && filters.type !== 'all') {
      discounts = discounts.filter((d) => d.type === filters.type)
    }
    return discounts.sort((a, b) => b.createdAt.localeCompare(a.createdAt))
  },

  async create(draft: DiscountDraft): Promise<Discount> {
    const now = new Date().toISOString()
    const discount: Discount = {
      id: `disc-${Date.now()}`,
      name: draft.name,
      code: draft.code.toUpperCase(),
      description: draft.description,
      type: draft.type,
      value: draft.value,
      condition: {
        minOrderValue: draft.minOrderValue,
        categoryIds: draft.categoryIds,
        productIds: draft.productIds,
        customerGroup: draft.customerGroup ?? 'all',
      },
      status: computeStatus(draft.startDate, draft.endDate),
      startDate: draft.startDate,
      endDate: draft.endDate,
      usageLimit: draft.usageLimit,
      usageCount: 0,
      perCustomerLimit: draft.perCustomerLimit,
      stackable: draft.stackable,
      oncePerCustomer: draft.oncePerCustomer,
      revenueImpacted: 0,
      createdAt: now,
      updatedAt: now,
    }
    return getRepositories().discounts.create(discount)
  },

  async update(id: string, updates: Partial<Discount>): Promise<Discount | null> {
    return getRepositories().discounts.update(id, updates)
  },

  async remove(id: string): Promise<boolean> {
    return getRepositories().discounts.remove(id)
  },

  async toggleStatus(id: string): Promise<Discount | null> {
    const d = await getRepositories().discounts.getById(id)
    if (!d) return null
    const next: DiscountStatus = d.status === 'disabled' ? computeStatus(d.startDate, d.endDate) : 'disabled'
    return getRepositories().discounts.update(id, { status: next })
  },
}
"}

{"path":"/c/Users/Arti/wakefit-clone/src/services/returnService.ts","content":"import { getRepositories } from '@/repositories/supabase'
import type { Return, ReturnStatus, ReturnReason, ReturnFilters as ReturnFiltersType } from '@/features/returns/types'

const RETURN_TRANSITIONS: Record<ReturnStatus, ReturnStatus[]> = {
  requested: ['approved', 'rejected'],
  approved: ['received'],
  received: ['inspected'],
  inspected: ['refunded', 'rejected'],
  refunded: [],
  rejected: [],
}

export const returnService = {
  async getAll(filters: ReturnFiltersType = {}): Promise<Return[]> {
    const repo = getRepositories()
    let returns = await repo.returns.getAll()

    if (filters.search) {
      const q = filters.search.toLowerCase()
      returns = returns.filter(
        (r) =>
          r.returnNumber.toLowerCase().includes(q) ||
          r.orderNumber.toLowerCase().includes(q) ||
          r.customerName.toLowerCase().includes(q) ||
          r.customerPhone.includes(q)
      )
    }

    if (filters.status && filters.status !== 'all') {
      returns = returns.filter((r) => r.status === filters.status)
    }

    if (filters.reason && filters.reason !== 'all') {
      returns = returns.filter((r) => r.reason === filters.reason)
    }

    if (filters.dateFrom) {
      returns = returns.filter((r) => r.createdAt >= filters.dateFrom!)
    }

    if (filters.dateTo) {
      returns = returns.filter((r) => r.createdAt <= filters.dateTo!)
    }

    return returns.sort((a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime())
  },

  async getById(id: string): Promise<Return | null> {
    const repo = getRepositories()
    return repo.returns.getById(id)
  },

  async getByOrderId(orderId: string): Promise<Return[]> {
    const repo = getRepositories()
    return repo.returns.getByOrderId(orderId)
  },

  async getByCustomerId(customerId: string): Promise<Return[]> {
    const repo = getRepositories()
    return repo.returns.getByCustomer(customerId)
  },

  getValidTransitions(currentStatus: ReturnStatus): ReturnStatus[] {
    return RETURN_TRANSITIONS[currentStatus] ?? []
  },

  async updateStatus(id: string, status: ReturnStatus, actor: string = 'Admin'): Promise<Return | null> {
    const repo = getRepositories()
    return repo.returns.updateStatus(id, status, actor)
  },

  async approve(id: string, actor: string = 'Admin'): Promise<Return | null> {
    return this.updateStatus(id, 'approved', actor)
  },

  async reject(id: string, actor: string = 'Admin'): Promise<Return | null> {
    return this.updateStatus(id, 'rejected', actor)
  },

  async markReceived(id: string, actor: string = 'Warehouse'): Promise<Return | null> {
    return this.updateStatus(id, 'received', actor)
  },

  async markInspected(id: string, actor: string = 'Quality'): Promise<Return | null> {
    return this.updateStatus(id, 'inspected', actor)
  },

  async processRefund(id: string, actor: string = 'Finance'): Promise<Return | null> {
    return this.updateStatus(id, 'refunded', actor)
  },

  async delete(id: string): Promise<boolean> {
    const repo = getRepositories()
    return repo.returns.delete(id)
  },
}
